        cmd = ['volume', 'select', volume['name'], 'access', 'create',
               'initiator', connector['initiator']]
        if self.configuration.eqlx_use_chap:
            cmd.extend(['authmethod chap', 'username',
                        self.configuration.eqlx_chap_login])
        self._eql_execute(*cmd)
        iscsi_properties = self._get_iscsi_properties(volume)
        return {
            'driver_volume_type': 'iscsi',
            'data': iscsi_properties
        }
    except Exception:
        with excutils.save_and_reraise_exception():
            LOG.error(_('Failed to initialize connection to volume %s'),
                      volume['name'])

def get_game_info(conn, game):

    cursor = conn.cursor()
    cursor.execute("SELECT player1,player2,size,state FROM games WHERE id = %d;", (game,))
    if cursor.rowcount != 1:
        raise FormError("Invalid game ID")

    row = cursor.fetchall()[0]
    players = [row[0],row[1]]
    size    =  row[2]
    state   =  row[3]

    if state is None:
         state = "Active"

    cursor.close()

    return (players,size,state)

