            return html`<span class="${classlist}"></span>${highlightFilterElements(
                    label,
                    filter_terms
                )}`;
        }

        return getHTMLStringFromTemplate(renderListItems(values, getValueRendered));
    }

function renderConnection(connection, user) {
  const replaced = {};
  Object.keys(connection).forEach((key) => {
    if (key === 'data') {
      const value = renderConnection(connection.data, user);
      connection.data = value;
    } else {
      const value = connection[key];
      if (typeof value === 'string') {
        replaced[key] = mustache.render(value, { user });
      } else {
        replaced[key] = value;
      }
    }
  });
  return replaced;
}

function _makeSetter( property, next ){
	if ( next ){
		return function setter( ctx, value ){
			var t = ctx[property];

			if ( !t ){
				t = ctx[property] = {};
			}

			return next( t, value );
		};
	}else{
		return function( ctx, value ){
			ctx[property] = value;
			return ctx;
		};
	}
}

